import{_ as a,c as i,o as t,ae as l}from"./chunks/framework.DZnj5e9o.js";const p=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/overview.md","filePath":"examples/overview.md"}'),o={name:"examples/overview.md"};function r(s,e,n,u,d,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><h2 id="query-mutation-inside-signal-store-local" tabindex="-1">Query &amp; Mutation inside signal store (local) <a class="header-anchor" href="#query-mutation-inside-signal-store-local" aria-label="Permalink to &quot;Query &amp; Mutation inside signal store (local)&quot;">​</a></h2><ul><li>Display a user</li><li>Toggle Api error via a checkbox</li><li>Mutate the user data <ul><li>Optimistic update the query state on mutate</li><li>Reload if the API return an error</li></ul></li></ul><h2 id="a-cached-global-query-and-mutation" tabindex="-1">A cached global query and mutation <a class="header-anchor" href="#a-cached-global-query-and-mutation" aria-label="Permalink to &quot;A cached global query and mutation&quot;">​</a></h2><ul><li>Display a user by using a cached global query</li><li>Plug the userId from the signal store to the global query</li><li>Toggle Api error via a checkbox</li><li>Mutate the user data <ul><li>Optimistic update the query state on mutate</li><li>Reload if the API return an error</li></ul></li></ul><h2 id="a-cached-global-query-used-without-store" tabindex="-1">A cached global query used without store <a class="header-anchor" href="#a-cached-global-query-used-without-store" aria-label="Permalink to &quot;A cached global query used without store&quot;">​</a></h2><ul><li>Display a user by using a cached global query without injecting a store (<code>injectUserQuery</code>)</li><li>Plug the userId from the component input to the global query</li><li>Use <code>preservePreviousValue</code> to preserve the previous user data during the new one to being fetch (may avoid flickering data)</li><li>Use <code>waitForParamsSrcToBeEqualToPreviousValue</code> to wait for the userId to be retrieved from the url before retrieve the data from cache (eg: if the cached user has id 2, and now the page userId is 3)</li></ul><h2 id="a-cached-global-query-byid-used-without-store" tabindex="-1">A cached global query (byId) used without store <a class="header-anchor" href="#a-cached-global-query-byid-used-without-store" aria-label="Permalink to &quot;A cached global query (byId) used without store&quot;">​</a></h2><ul><li>Display a user by using a cached global query without injecting a store (<code>injectUserQueryById</code>) <ul><li>Compare to a simple <code>query</code> This enable to cache all visited user page (instead of the last user visited when using <code>query</code>)</li></ul></li><li>Plug the userId from the component input to the global query</li><li>Use <code>insertPlaceholderData</code> to display the data from the previous visited page while the new user data load</li></ul><h2 id="list-with-pagination-local-query" tabindex="-1">List with pagination (Local query) <a class="header-anchor" href="#list-with-pagination-local-query" aria-label="Permalink to &quot;List with pagination (Local query)&quot;">​</a></h2><ul><li>Display a paginated list of user (previous page, next page, page size)</li><li>Use <code>insertPaginationPlaceholderData</code> to easily display the current page data and a placeholder data while the next page data is loading</li></ul><h2 id="list-with-cached-pagination-global-query" tabindex="-1">List with cached pagination (Global query) <a class="header-anchor" href="#list-with-cached-pagination-global-query" aria-label="Permalink to &quot;List with cached pagination (Global query)&quot;">​</a></h2><ul><li>Display a paginated list of user (previous page, next page, page size)</li><li>Using a cached (from localStorage) global query, that is plugged inside a signalStore</li><li>Use <code>insertPaginationPlaceholderData</code> to easily display the current page data and a placeholder data while the next page data is loading</li></ul><h2 id="list-with-pagination-and-granular-mutations" tabindex="-1">List with pagination and granular mutations <a class="header-anchor" href="#list-with-pagination-and-granular-mutations" aria-label="Permalink to &quot;List with pagination and granular mutations&quot;">​</a></h2><ul><li>Display a paginated list of user (previous page, next page, page size)</li><li>Using a cached (from localStorage) global query, that is plugged inside a signalStore</li><li>Edit user name concurrently (click on the <code>Update</code> button of multiples items)</li></ul><h2 id="display-x-independents-resources-to-display-and-granular-mutations" tabindex="-1">Display X independents resources to display and granular mutations <a class="header-anchor" href="#display-x-independents-resources-to-display-and-granular-mutations" aria-label="Permalink to &quot;Display X independents resources to display and granular mutations&quot;">​</a></h2><ul><li>Available soon</li><li>Display a dynamic list of selected user</li><li>Apply granular mutation on selected user</li><li>Pokemon</li></ul>',17)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
